// GENERADO por backend/herramientas/generar_aprende.py a partir de backend/retos/conceptos/github.py. No lo edites a mano: cambia los conceptos y vuelve a generarlo.
// m = etapa · t = título · x = qué es · u = para qué sirve · p = puntos clave · c = código · h = qué hace · r = ahora tú · e = error común
export default [
  {"m": "Empieza en GitHub", "t": "Qué es GitHub", "x": "Plataforma en la nube para guardar repositorios de Git y colaborar.\n\nGitHub guarda repositorios de Git en internet y agrega herramientas: issues, pull requests, Actions y Pages. Git es la herramienta que usas en tu computador; GitHub es el sitio donde se comparte. Alternativas: GitLab y Bitbucket.", "u": "Tener tu código en línea, trabajar en equipo y mostrar tu portafolio.\n\nQuieres guardar tu proyecto en internet, que tu equipo trabaje en él y que las empresas vean tu código.", "p": ["GitHub guarda repositorios de Git en la nube.", "Git funciona en tu computador y GitHub en internet.", "GitLab y Bitbucket son alternativas a GitHub."], "c": "git remote add origin https://github.com/ana/tienda.git\ngit push -u origin main", "h": "Sube un repositorio local a GitHub.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La plataforma más usada para alojar repositorios de Git es ___. (6 letras)", "e": "Creer que Git y GitHub son lo mismo."},
  {"m": "Empieza en GitHub", "t": "Repositorio en GitHub", "x": "Proyecto alojado en GitHub con su código, historial y configuración.\n\nCon el botón New eliges nombre, si es público o privado y si agregas README, .gitignore y licencia. La dirección queda github.com/usuario/repositorio. Los repositorios privados solo los ven las personas que invites.", "u": "Tener un lugar para cada proyecto, público o privado.\n\nEmpiezas un proyecto nuevo y quieres que solo tú y tu profesor puedan ver el código en GitHub.", "p": ["Un repositorio puede ser público o privado.", "La URL de un repositorio es github.com/usuario/nombre.", "Al crear un repositorio puedes agregar README y licencia."], "c": "gh repo create tienda --private --clone", "h": "Crea un repositorio privado y lo clona.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un repositorio que solo ven las personas invitadas es ___. (7 letras)", "e": "Subir claves a un repositorio público."},
  {"m": "Empieza en GitHub", "t": "README y Markdown", "x": "Archivo de portada del repositorio escrito en Markdown.\n\nGitHub muestra README.md en la página principal del repositorio. Markdown usa # para títulos, **negrita**, - para listas, [texto](url) para enlaces y ``` para bloques de código. Un buen README dice qué es, cómo instalarlo y cómo usarlo.", "u": "Explicar qué hace el proyecto y cómo usarlo.\n\nCualquiera que entra a tu repositorio no entiende qué hace ni cómo ejecutarlo.", "p": ["GitHub muestra README.md en la portada del repositorio.", "En Markdown, # crea un título.", "Un README explica cómo instalar y usar el proyecto."], "c": "# Tienda\nApp para vender productos.\n\n## Cómo iniciarla\n```\nnpm install\nnpm run dev\n```", "h": "Un README con título, descripción e instrucciones.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El archivo de portada de un repositorio es README.___. (2 letras)", "e": "Dejar el README vacío o solo con el nombre del proyecto."},
  {"m": "Empieza en GitHub", "t": "Licencias", "x": "Texto que dice qué pueden hacer otros con tu código.\n\nSin licencia, nadie puede reutilizar legalmente tu código aunque sea público. MIT permite casi todo con atribución; GPL obliga a que los derivados también sean libres; Apache 2.0 agrega protección de patentes. Se guarda en el archivo LICENSE.", "u": "Permitir o limitar que otros usen, cambien o vendan tu proyecto.\n\nPublicaste una librería y quieres que cualquiera la use, incluso en proyectos comerciales, solo dándote crédito.", "p": ["Sin licencia nadie puede reutilizar legalmente tu código.", "MIT es una licencia muy permisiva.", "La licencia se guarda en el archivo LICENSE."], "c": "MIT License\n\nCopyright (c) 2026 Ana", "h": "Comienzo del archivo LICENSE con licencia MIT.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La licencia permisiva más usada es ___. (3 letras)", "e": "Copiar código de un repositorio sin licencia y usarlo como propio."},
  {"m": "Empieza en GitHub", "t": "Subir archivos desde la web", "x": "Agregar o editar archivos directamente en github.com.\n\nEn el repositorio, Add file → Upload files sube archivos arrastrándolos y el lápiz edita uno. Cada cambio pide un mensaje y crea un commit. Para trabajo diario es mejor clonar y usar Git o VS Code.", "u": "Hacer cambios pequeños sin usar la terminal.\n\nNecesitas corregir un error de ortografía en el README desde el celular, sin Git instalado.", "p": ["En la web, cada cambio crea un commit.", "Upload files sube archivos arrastrándolos.", "El ícono del lápiz edita un archivo en GitHub."], "c": "# En github.com: abre README.md → ícono del lápiz → edita\n# → Commit changes… → mensaje: \"Corrige ortografía\"", "h": "Pasos para editar un archivo desde la web.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En la web de GitHub, cada cambio guardado crea un ___. (6 letras)", "e": "Editar en la web y olvidar hacer pull antes de seguir en tu computador."},
  {"m": "Empieza en GitHub", "t": "Clonar con HTTPS", "x": "Descargar un repositorio de GitHub con su historial usando la URL https.\n\nEl botón verde Code muestra la URL; git clone URL crea la carpeta con todo el historial. Para hacer push por HTTPS, GitHub pide un token personal (no la contraseña) o usar GitHub CLI o Git Credential Manager.", "u": "Trabajar en tu computador en un proyecto que está en GitHub.\n\nTu compañero creó el repositorio del proyecto en GitHub y necesitas tenerlo en tu computador.", "p": ["El botón Code muestra la URL para clonar.", "git clone descarga todo el historial.", "Para push por HTTPS se usa un token, no la contraseña."], "c": "git clone https://github.com/ana/tienda.git\ncd tienda", "h": "Clona un repositorio y entra en su carpeta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El botón de GitHub con la URL para clonar es el botón ___. (4 letras)", "e": "Intentar hacer push con la contraseña de la cuenta."},
  {"m": "Empieza en GitHub", "t": "GitHub Desktop", "x": "Aplicación gráfica oficial para usar Git y GitHub.\n\nGitHub Desktop muestra los cambios, permite escribir el mensaje del commit, cambiar de rama y sincronizar (pull y push) con un botón. VS Code también tiene un panel de Git integrado. Entender las órdenes sigue siendo importante.", "u": "Hacer commits, ramas y push con botones en lugar de órdenes.\n\nTu compañera de diseño quiere subir cambios al repositorio pero no le gusta la terminal.", "p": ["GitHub Desktop es la aplicación gráfica oficial de GitHub.", "GitHub Desktop sincroniza con un botón.", "VS Code tiene un panel de Git integrado."], "c": "# GitHub Desktop: Changes → escribe el resumen → Commit to main → Push origin", "h": "Pasos para hacer commit y push con la aplicación.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La aplicación gráfica oficial de GitHub es GitHub ___. (7 letras)", "e": "Hacer commit de todos los archivos sin mirar qué cambió."},
  {"m": "Empieza en GitHub", "t": "Explorar GitHub", "x": "Estrellas, seguimiento, temas y búsqueda de repositorios.\n\nStar guarda un repositorio en tus favoritos (y muestra su popularidad), Watch te avisa de su actividad y Topics agrupan por tema. La búsqueda acepta filtros como language:python stars:>1000.", "u": "Encontrar proyectos para aprender y seguir los que te interesan.\n\nEncontraste un repositorio de ejemplos de FastAPI y quieres guardarlo para volver luego.", "p": ["Star guarda un repositorio en favoritos.", "Watch avisa de la actividad de un repositorio.", "La búsqueda acepta filtros como language:python."], "c": "# En la búsqueda de GitHub:\nlanguage:python stars:>1000 fastapi", "h": "Busca repositorios de Python populares sobre FastAPI.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El botón que guarda un repositorio en favoritos es ___. (4 letras)", "e": "Medir la calidad de un proyecto solo por sus estrellas."},
  {"m": "Colabora en equipo", "t": "Issues", "x": "Tarjetas para reportar errores, pedir funciones o anotar tareas.\n\nUn issue tiene título, descripción, comentarios, etiquetas y responsables. Se cierran solos si un commit o pull request dice «Fixes #12». Las plantillas de issues piden la información necesaria para reportar bien un error.", "u": "Organizar el trabajo pendiente de un proyecto.\n\nUn usuario encontró un error en tu app y quieres dejarlo registrado para arreglarlo después.", "p": ["Un issue reporta un error o pide una función.", "«Fixes #12» cierra el issue 12 al unir el cambio.", "Los issues pueden tener etiquetas y responsables."], "c": "gh issue create --title \"El botón Pagar no responde\" --label bug", "h": "Crea un issue con la etiqueta bug.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En GitHub, un reporte de error o tarea se llama ___. (5 letras)", "e": "Reportar «no funciona» sin pasos para reproducir el error."},
  {"m": "Colabora en equipo", "t": "Etiquetas y responsables", "x": "Formas de clasificar issues y asignar quién los atiende.\n\nLabels como bug, enhancement o good first issue clasifican; Assignees indica quién trabaja en algo y Milestones agrupa issues de una versión o entrega. good first issue invita a personas nuevas a contribuir.", "u": "Saber de un vistazo qué es urgente y quién se encarga.\n\nTu equipo tiene 40 issues y no se sabe cuáles son errores ni quién se encarga de cada uno.", "p": ["Las labels clasifican los issues.", "Assignees indica quién trabaja en un issue.", "Milestones agrupa issues de una entrega."], "c": "gh issue edit 12 --add-label bug --add-assignee ana --milestone \"v1.0\"", "h": "Etiqueta, asigna y agrupa un issue.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La etiqueta para invitar a personas nuevas es good first ___. (5 letras)", "e": "Tener issues sin etiqueta ni responsable que nadie atiende."},
  {"m": "Colabora en equipo", "t": "Pull request en GitHub", "x": "Propuesta para unir los cambios de una rama a otra, con revisión.\n\nSubes tu rama, GitHub ofrece Compare & pull request y escribes qué cambia y por qué. Se ven los archivos cambiados, las pruebas y los comentarios. Al final se une con Merge, Squash and merge o Rebase and merge.", "u": "Que el equipo revise y discuta los cambios antes de unirlos.\n\nTerminaste la función del carrito en tu rama y quieres que tu equipo la revise antes de unirla a main.", "p": ["Un pull request propone unir una rama a otra.", "En un pull request se ven los archivos cambiados.", "Squash and merge une todos los commits en uno."], "c": "git push -u origin carrito\ngh pr create --title \"Agrega carrito\" --body \"Cierra #8\"", "h": "Sube la rama y abre un pull request.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción que une todos los commits del pull request en uno es ___ and merge. (6 letras)", "e": "Abrir pull requests sin descripción."},
  {"m": "Colabora en equipo", "t": "Revisar un pull request", "x": "Leer los cambios, comentar líneas y aprobar o pedir cambios.\n\nEn Files changed comentas líneas concretas y con Suggest changes propones el código exacto. Al terminar eliges Comment, Approve o Request changes. El autor responde, corrige y la conversación se marca como resuelta.", "u": "Mejorar la calidad del código antes de unirlo.\n\nRevisas el pull request de un compañero y encontraste un error que debe corregir antes de unirlo.", "p": ["En Files changed se comentan líneas concretas.", "Request changes pide correcciones antes de unir.", "Suggest changes propone el código exacto."], "c": "```suggestion\nconst total = precio * cantidad;\n```", "h": "Una sugerencia de código en un comentario de revisión.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La pestaña donde se ven los cambios del PR es Files ___. (7 letras)", "e": "Hacer comentarios vagos como «esto está mal» sin explicar."},
  {"m": "Colabora en equipo", "t": "Conflictos en GitHub", "x": "Cuando el pull request no se puede unir porque main cambió las mismas líneas.\n\nGitHub avisa «This branch has conflicts». Para conflictos simples, Resolve conflicts abre un editor con las marcas <<<<<<< ======= >>>>>>>. Si son complejos, haces git merge main en tu rama, los resuelves en VS Code y vuelves a hacer push.", "u": "Resolver choques de cambios antes de unir.\n\nTu pull request dice «This branch has conflicts that must be resolved».", "p": ["GitHub avisa cuando un pull request tiene conflictos.", "Resolve conflicts permite arreglarlos en la web.", "Las marcas <<<<<<< y >>>>>>> separan las dos versiones."], "c": "git switch carrito\ngit merge main\n# arregla los archivos en VS Code\ngit commit -am \"Resuelve conflicto con main\" && git push", "h": "Trae main a tu rama, resuelve y sube.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El botón de GitHub para arreglar conflictos en la web es Resolve ___. (9 letras)", "e": "Borrar la versión del compañero sin hablar con él."},
  {"m": "Colabora en equipo", "t": "Colaboradores y permisos", "x": "Personas con acceso a tu repositorio y su nivel de permiso.\n\nEn Settings → Collaborators invitas por usuario o correo. En organizaciones hay roles: Read, Triage, Write, Maintain y Admin. Da el permiso mínimo necesario.", "u": "Que tu equipo pueda subir cambios a un repositorio.\n\nTu compañero de proyecto no puede hacer push a tu repositorio y le sale «Permission denied».", "p": ["Los colaboradores se invitan en Settings.", "El rol Write permite subir cambios.", "Conviene dar el permiso mínimo necesario."], "c": "gh api repos/ana/tienda/collaborators/luis -X PUT -f permission=push", "h": "Invita a luis con permiso de escritura.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La persona con acceso a tu repositorio es un ___. (11 letras)", "e": "Darle permiso Admin a todo el mundo."},
  {"m": "Colabora en equipo", "t": "Discussions", "x": "Foro dentro del repositorio para preguntas e ideas.\n\nDiscussions tiene categorías como Q&A, Ideas y Anuncios; en Q&A se marca la mejor respuesta. Así los issues quedan solo para trabajo concreto. Se activa en Settings → Features.", "u": "Separar las conversaciones generales de los issues.\n\nTus usuarios abren issues para hacer preguntas de cómo usar la librería y se llena de ruido.", "p": ["Discussions es un foro dentro del repositorio.", "En Q&A se marca la mejor respuesta.", "Discussions se activa en Settings."], "c": "# Settings → Features → ✓ Discussions\n# Categoría «Q&A» → marca «Mark as answer»", "h": "Activa Discussions y marca una respuesta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El foro integrado en un repositorio se llama ___. (11 letras)", "e": "Dejar preguntas generales mezcladas con los errores."},
  {"m": "Colabora en equipo", "t": "Plantillas de issues y PR", "x": "Formularios con secciones que se rellenan al abrir un issue o PR.\n\nEn .github/ISSUE_TEMPLATE/ creas formularios para errores y peticiones, y .github/pull_request_template.md da el esquema de cada PR. Así nadie olvida los pasos para reproducir ni la lista de verificación.", "u": "Recibir reportes completos y descripciones consistentes.\n\nLos reportes de errores llegan sin pasos para reproducir ni versión del navegador.", "p": ["Las plantillas viven en la carpeta .github.", "ISSUE_TEMPLATE guarda formularios de issues.", "pull_request_template.md da el esquema de los PR."], "c": "<!-- .github/pull_request_template.md -->\n## Qué cambia\n## Cómo probarlo\n- [ ] Probé en el navegador", "h": "Plantilla de descripción de pull request.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las plantillas se guardan en la carpeta .___. (6 letras)", "e": "Hacer plantillas tan largas que nadie las llena."},
  {"m": "GitHub Actions", "t": "CI/CD", "x": "Integración y entrega continuas: probar y publicar automáticamente cada cambio.\n\nCI (integración continua) ejecuta las pruebas en cada push o pull request. CD (entrega o despliegue continuo) publica automáticamente lo que pasa las pruebas. En GitHub se hace con GitHub Actions.", "u": "Detectar errores pronto y desplegar sin pasos manuales.\n\nTu equipo olvida correr las pruebas antes de unir cambios y se rompe main seguido.", "p": ["CI ejecuta las pruebas en cada cambio.", "CD publica automáticamente lo que pasa las pruebas.", "GitHub Actions hace CI/CD en GitHub."], "c": "# .github/workflows/pruebas.yml\non: [push, pull_request]", "h": "Un flujo que corre en cada push y pull request.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las siglas de integración y entrega continuas son ci/___. (2 letras)", "e": "Unir cambios sin esperar a que terminen las pruebas."},
  {"m": "GitHub Actions", "t": "Workflow YAML", "x": "Archivo en .github/workflows que describe una automatización.\n\nUn workflow tiene name, on (cuándo corre) y jobs (qué hace). Se escribe en YAML: la sangría con espacios importa. En la pestaña Actions del repositorio ves cada ejecución con sus registros.", "u": "Definir cuándo y qué ejecuta GitHub Actions.\n\nQuieres automatizar las pruebas de tu proyecto en GitHub.", "p": ["Los workflows viven en .github/workflows.", "La clave on define cuándo corre un workflow.", "En YAML la sangría con espacios es importante."], "c": "name: Pruebas\non: [push]\njobs:\n  probar:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: npm ci && npm test", "h": "Workflow que instala dependencias y corre las pruebas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los workflows se guardan en .github/___. (9 letras)", "e": "Usar tabulaciones en el YAML y que el workflow no se lea."},
  {"m": "GitHub Actions", "t": "Eventos de un workflow", "x": "Lo que dispara un workflow: push, pull_request, schedule, workflow_dispatch.\n\npush corre en cada push (se puede filtrar por branches), pull_request al abrir o actualizar un PR, schedule con sintaxis cron y workflow_dispatch añade un botón para ejecutarlo a mano.", "u": "Ejecutar la automatización en el momento adecuado.\n\nQuieres poder lanzar el despliegue con un botón desde la pestaña Actions, no en cada push.", "p": ["push dispara el workflow en cada push.", "schedule ejecuta un workflow con sintaxis cron.", "workflow_dispatch permite ejecutarlo a mano."], "c": "on:\n  push:\n    branches: [main]\n  schedule:\n    - cron: \"0 6 * * 1\"", "h": "Corre en push a main y cada lunes a las 6.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El evento que permite ejecutar un workflow a mano es workflow___. (9 caracteres)", "e": "Ejecutar el despliegue en pull requests de cualquier rama."},
  {"m": "GitHub Actions", "t": "Jobs y steps", "x": "Tareas de un workflow y los pasos dentro de cada una.\n\nCada job corre en una máquina nueva (runs-on). Sus steps son acciones (uses) u órdenes (run) en orden. Los jobs corren en paralelo, salvo que uno dependa de otro con needs.", "u": "Dividir la automatización en partes que pueden correr en paralelo.\n\nTu workflow tiene un job de pruebas y otro de despliegue; el despliegue solo debe correr si las pruebas pasaron.", "p": ["Cada job corre en una máquina nueva.", "Los steps se ejecutan en orden.", "needs hace que un job espere a otro."], "c": "jobs:\n  probar: { runs-on: ubuntu-latest, steps: [{ run: npm test }] }\n  desplegar:\n    needs: probar\n    runs-on: ubuntu-latest\n    steps: [{ run: ./desplegar.sh }]", "h": "El despliegue espera a las pruebas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La clave que hace que un job espere a otro es ___. (5 letras)", "e": "Poner todo en un solo job enorme."},
  {"m": "GitHub Actions", "t": "Acciones del Marketplace", "x": "Pasos reutilizables que otros publicaron para GitHub Actions.\n\nactions/checkout descarga tu código, actions/setup-node y actions/setup-python instalan la versión que pides y actions/cache acelera las dependencias. Fija la versión (@v4) y revisa quién publica cada acción.", "u": "No escribir desde cero tareas comunes.\n\nTu workflow necesita Python 3.12 instalado antes de correr las pruebas.", "p": ["actions/checkout descarga el código del repositorio.", "setup-node instala una versión de Node.", "Conviene fijar la versión de cada acción."], "c": "- uses: actions/setup-python@v5\n  with:\n    python-version: \"3.12\"\n- run: pip install -r requirements.txt && pytest", "h": "Instala Python 3.12 y corre las pruebas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La acción que descarga tu código es actions/___. (8 letras)", "e": "Usar acciones de autores desconocidos sin revisar."},
  {"m": "GitHub Actions", "t": "Secretos de GitHub", "x": "Valores cifrados que los workflows usan sin mostrarlos.\n\nSe crean en Settings → Secrets and variables → Actions y se usan como ${{ secrets.NOMBRE }}. GitHub los oculta en los registros. GITHUB_TOKEN viene incluido y sirve para operar sobre el propio repositorio.", "u": "Usar claves y tokens en Actions sin escribirlos en el código.\n\nTu workflow debe desplegar en un servidor y necesita su contraseña, pero el repositorio es público.", "p": ["Los secretos se usan con ${{ secrets.NOMBRE }}.", "GitHub oculta los secretos en los registros.", "GITHUB_TOKEN viene incluido en cada workflow."], "c": "- run: ./desplegar.sh\n  env:\n    CLAVE: ${{ secrets.CLAVE_SERVIDOR }}", "h": "Usa un secreto como variable de entorno.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los valores cifrados para Actions se llaman ___. (8 letras)", "e": "Imprimir un secreto en los registros con echo."},
  {"m": "GitHub Actions", "t": "Matrices", "x": "Estrategia que corre el mismo job con varias combinaciones.\n\nstrategy.matrix con node: [18, 20, 22] y os: [ubuntu-latest, windows-latest] crea un job por combinación. Así sabes si tu librería funciona en todas. fail-fast: false deja terminar las demás aunque una falle.", "u": "Probar tu código en varias versiones y sistemas a la vez.\n\nTu librería debe funcionar en Node 18, 20 y 22, en Linux y Windows.", "p": ["Una matriz crea un job por combinación.", "Con matrices se prueba en varias versiones a la vez.", "fail-fast: false deja terminar las demás combinaciones."], "c": "strategy:\n  matrix:\n    node: [18, 20, 22]\n    os: [ubuntu-latest, windows-latest]\nruns-on: ${{ matrix.os }}", "h": "Seis combinaciones de versión y sistema.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La clave de Actions para probar varias combinaciones es ___. (6 letras)", "e": "Crear seis workflows copiados en lugar de una matriz."},
  {"m": "GitHub Actions", "t": "Artefactos", "x": "Archivos que un workflow guarda para descargar o usar en otro job.\n\nactions/upload-artifact guarda archivos (por ejemplo, dist/ o un informe) y actions/download-artifact los recupera en otro job. Se descargan desde la ejecución en la pestaña Actions y caducan a los 90 días por defecto.", "u": "Conservar el resultado de un build o un informe de pruebas.\n\nTu workflow compila la app y quieres descargar la carpeta dist que generó para revisarla.", "p": ["Los artefactos guardan archivos de un workflow.", "upload-artifact sube archivos de la ejecución.", "Los artefactos caducan después de un tiempo."], "c": "- uses: actions/upload-artifact@v4\n  with:\n    name: web\n    path: dist/", "h": "Guarda la carpeta dist como artefacto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los archivos que guarda un workflow se llaman ___. (10 letras)", "e": "Guardar artefactos enormes en cada ejecución."},
  {"m": "Publica y comparte", "t": "GitHub Pages", "x": "Hosting gratis de páginas estáticas desde un repositorio.\n\nEn Settings → Pages eliges la rama (o GitHub Actions para Vite/React). La web queda en usuario.github.io/repositorio, o en usuario.github.io si el repositorio se llama así. Solo sirve archivos estáticos: no ejecuta PHP ni Python.", "u": "Publicar tu portafolio o la web de un proyecto.\n\nTerminaste tu portafolio en HTML, CSS y JS y quieres publicarlo gratis con una URL.", "p": ["GitHub Pages publica páginas estáticas gratis.", "Pages no ejecuta código de servidor.", "El repositorio usuario.github.io es tu sitio principal."], "c": "# Settings → Pages → Source: Deploy from a branch → main / (root)\n# https://ana.github.io/portafolio/", "h": "Publica la rama main con Pages.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El servicio de GitHub para publicar páginas estáticas es GitHub ___. (5 letras)", "e": "Intentar publicar una app de PHP o Flask en Pages."},
  {"m": "Publica y comparte", "t": "Releases", "x": "Versiones publicadas con notas y archivos descargables.\n\nUn release se basa en una etiqueta (v1.2.0), tiene notas de cambios (GitHub las genera solas) y archivos adjuntos como instaladores o .zip. gh release create v1.2.0 --generate-notes lo hace desde la terminal.", "u": "Entregar versiones de tu proyecto a los usuarios.\n\nTerminaste la versión 1.0 de tu app de escritorio y quieres que la gente descargue el instalador.", "p": ["Un release se basa en una etiqueta de Git.", "Los releases pueden llevar archivos adjuntos.", "GitHub genera las notas de cambios automáticamente."], "c": "gh release create v1.0.0 instalador.exe --generate-notes", "h": "Publica una versión con su instalador.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una versión publicada en GitHub se llama ___. (7 letras)", "e": "Publicar versiones sin notas de qué cambió."},
  {"m": "Publica y comparte", "t": "GitHub Packages", "x": "Registro de paquetes y contenedores integrado en GitHub.\n\nGitHub Container Registry (ghcr.io) guarda imágenes de Docker y GitHub Packages también aloja paquetes npm, Maven o NuGet. Se autentica con GITHUB_TOKEN en Actions y los permisos siguen a los del repositorio.", "u": "Publicar librerías npm o imágenes Docker junto a tu código.\n\nQuieres publicar la imagen Docker de tu API en el mismo lugar donde está tu código.", "p": ["ghcr.io guarda imágenes de Docker.", "GitHub Packages aloja paquetes npm.", "En Actions se autentica con GITHUB_TOKEN."], "c": "docker tag mi-api ghcr.io/ana/mi-api:1.0\ndocker push ghcr.io/ana/mi-api:1.0", "h": "Sube una imagen al registro de GitHub.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El registro de paquetes integrado se llama GitHub ___. (8 letras)", "e": "Publicar imágenes privadas como públicas por error."},
  {"m": "Publica y comparte", "t": "Gists", "x": "Fragmentos de código que se comparten con un enlace.\n\nEn gist.github.com pegas uno o varios archivos y obtienes un enlace. Pueden ser públicos o secretos (no listados, pero accesibles con el enlace). Cada gist es un pequeño repositorio de Git.", "u": "Compartir un ejemplo o una configuración sin crear un repositorio.\n\nQuieres compartir con tu profesor un archivo de configuración de 20 líneas sin crear un repositorio.", "p": ["Un gist comparte fragmentos de código con un enlace.", "Un gist secreto no aparece en listados.", "Cada gist es un pequeño repositorio de Git."], "c": "gh gist create config.json --desc \"Mi configuración\"", "h": "Crea un gist desde la terminal.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un fragmento de código compartido con enlace en GitHub es un ___. (4 letras)", "e": "Creer que un gist secreto es privado y poner claves."},
  {"m": "Publica y comparte", "t": "GitHub CLI", "x": "Herramienta gh para usar GitHub desde la terminal.\n\ngh auth login inicia sesión; gh repo create, gh issue list, gh pr create y gh pr checkout cubren el trabajo diario. También configura Git para hacer push por HTTPS sin tokens a mano.", "u": "Crear repositorios, issues y pull requests sin abrir el navegador.\n\nQuieres revisar en tu computador el pull request #15 de un compañero con una sola orden.", "p": ["gh es la terminal oficial de GitHub.", "gh auth login inicia sesión en GitHub.", "gh pr checkout descarga un pull request."], "c": "gh auth login\ngh pr checkout 15", "h": "Inicia sesión y descarga un pull request.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden de la terminal de GitHub es ___. (2 letras)", "e": "Crear tokens a mano en lugar de usar gh auth login."},
  {"m": "Publica y comparte", "t": "Codespaces", "x": "Entorno de VS Code en la nube para cualquier repositorio.\n\nDesde Code → Codespaces se abre VS Code en el navegador con una máquina Linux en la nube y el repositorio listo. El archivo .devcontainer/devcontainer.json define qué herramientas instala. Tiene horas gratis al mes.", "u": "Programar desde cualquier computador sin instalar nada.\n\nEstás en un computador de la biblioteca sin permisos para instalar nada y debes trabajar en tu repositorio.", "p": ["Codespaces abre VS Code en la nube.", "devcontainer.json define el entorno de Codespaces.", "Codespaces tiene horas gratis al mes."], "c": "{\n  \"image\": \"mcr.microsoft.com/devcontainers/python:3.12\",\n  \"postCreateCommand\": \"pip install -r requirements.txt\"\n}", "h": "Devcontainer.json con Python y dependencias.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El entorno de VS Code en la nube de GitHub es ___. (10 letras)", "e": "Dejar codespaces encendidos y gastar las horas gratis."},
  {"m": "Publica y comparte", "t": "Repositorios plantilla", "x": "Repositorios marcados como plantilla para crear otros iguales.\n\nEn Settings marcas Template repository y aparece el botón Use this template. El repositorio nuevo copia archivos y carpetas pero no el historial. Muy útil para proyectos de clase con la misma base.", "u": "Empezar proyectos nuevos con la estructura lista.\n\nCada semestre creas el mismo esqueleto de proyecto Flask para tus estudiantes.", "p": ["Una plantilla crea repositorios con la misma estructura.", "El botón Use this template crea la copia.", "El repositorio nuevo no copia el historial."], "c": "gh repo create proyecto-final --template ana/plantilla-flask --private", "h": "Crea un repositorio desde una plantilla.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El botón para crear desde una plantilla es Use this ___. (8 letras)", "e": "Hacer fork para empezar proyectos que no vas a devolver al original."},
  {"m": "Publica y comparte", "t": "Wiki y proyectos de documentación", "x": "Espacio de documentación de un repositorio.\n\nCada repositorio puede tener una Wiki con páginas en Markdown y su propio historial. Para documentación grande se suele usar una carpeta docs/ con un generador (MkDocs, Docusaurus) publicado en Pages.", "u": "Guardar guías largas fuera del README.\n\nTu README ya es enorme con guías de instalación, arquitectura y API.", "p": ["La Wiki guarda páginas de documentación en Markdown.", "La carpeta docs/ puede publicarse con Pages.", "MkDocs genera sitios de documentación."], "c": "git clone https://github.com/ana/tienda.wiki.git", "h": "Clona la wiki de un repositorio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El espacio de documentación de un repositorio es la ___. (4 letras)", "e": "Tener la documentación desactualizada respecto al código."},
  {"m": "Seguridad y comunidad", "t": "Dependabot", "x": "Robot de GitHub que avisa y actualiza dependencias vulnerables.\n\nDependabot alerts avisa si una dependencia tiene una vulnerabilidad conocida y Dependabot security updates abre el pull request que la corrige. Con .github/dependabot.yml también propone actualizaciones de versión cada semana.", "u": "Mantener las librerías al día sin revisarlas a mano.\n\nUna librería que usas tiene una vulnerabilidad grave y no te enteraste.", "p": ["Dependabot avisa de dependencias vulnerables.", "Dependabot abre pull requests de actualización.", "dependabot.yml configura las actualizaciones."], "c": "# .github/dependabot.yml\nversion: 2\nupdates:\n  - package-ecosystem: npm\n    directory: \"/\"\n    schedule: { interval: weekly }", "h": "Actualizaciones semanales de npm.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El robot de GitHub que actualiza dependencias es ___. (10 letras)", "e": "Ignorar las alertas de Dependabot durante meses."},
  {"m": "Seguridad y comunidad", "t": "Code scanning", "x": "Análisis automático del código para encontrar vulnerabilidades.\n\nCode scanning usa CodeQL para revisar el código en cada push o pull request y muestra las alertas en la pestaña Security. Es gratis en repositorios públicos. Se activa con el workflow de CodeQL.", "u": "Detectar inyecciones SQL, XSS y otros fallos antes de publicar.\n\nQuieres que GitHub revise automáticamente si tu código tiene una inyección SQL antes de unir cada pull request.", "p": ["Code scanning busca vulnerabilidades en el código.", "Code scanning usa CodeQL.", "Las alertas aparecen en la pestaña Security."], "c": "- uses: github/codeql-action/init@v3\n  with: { languages: python }\n- uses: github/codeql-action/analyze@v3", "h": "Analiza el código de Python con CodeQL.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El motor de análisis de code scanning es ___. (6 letras)", "e": "Desactivar las alertas en lugar de corregirlas."},
  {"m": "Seguridad y comunidad", "t": "Secret scanning", "x": "Detección de claves y tokens subidos por error.\n\nGitHub revisa los commits buscando tokens conocidos (AWS, Stripe, GitHub…). Con push protection bloquea el push antes de que el secreto llegue. Si ya se subió, cambia la clave: borrarlo del archivo no basta porque queda en el historial.", "u": "Evitar que tus credenciales queden expuestas.\n\nSubiste por error tu archivo .env con la clave de la base de datos a GitHub.", "p": ["Secret scanning detecta claves subidas por error.", "Push protection bloquea el push con secretos.", "Una clave filtrada se debe cambiar."], "c": "git push\n# remote: error: GH013: Repository rule violations found\n# remote: - Push cannot contain secrets", "h": "Push bloqueado porque contiene un secreto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que bloquea el push con secretos es push ___. (10 letras)", "e": "Borrar el archivo en un commit nuevo y creer que ya no está."},
  {"m": "Seguridad y comunidad", "t": "Autenticación en dos pasos", "x": "Segundo factor para entrar a tu cuenta además de la contraseña.\n\nGitHub exige 2FA a quienes publican código. Puedes usar una app (Google Authenticator, Authy), llaves de seguridad o passkeys. Guarda los códigos de recuperación en un lugar seguro.", "u": "Que nadie entre a tu cuenta aunque sepa tu contraseña.\n\nAlguien consiguió tu contraseña de GitHub de una filtración.", "p": ["2FA agrega un segundo factor a la contraseña.", "GitHub exige 2FA a quienes publican código.", "Los códigos de recuperación permiten entrar si pierdes el celular."], "c": "# Settings → Password and authentication → Enable two-factor authentication", "h": "Activa la autenticación en dos pasos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las siglas de autenticación en dos pasos son ___. (3 caracteres)", "e": "No guardar los códigos de recuperación."},
  {"m": "Seguridad y comunidad", "t": "GitHub Projects", "x": "Tableros y tablas para planificar el trabajo con issues y PR.\n\nUn Project reúne issues y pull requests de uno o varios repositorios en vistas de tablero (Por hacer, En progreso, Hecho), tabla o cronograma. Tiene campos propios como prioridad o fecha y automatizaciones.", "u": "Organizar un proyecto como un tablero Kanban.\n\nTu equipo quiere ver en columnas qué tareas están por hacer, en progreso y terminadas.", "p": ["GitHub Projects organiza issues en tableros.", "Projects tiene vistas de tablero, tabla y cronograma.", "Un Project puede incluir varios repositorios."], "c": "gh project create --owner ana --title \"Sprint 1\"", "h": "Crea un tablero de proyecto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La herramienta de tableros de GitHub es GitHub ___. (8 letras)", "e": "Tener el tablero desactualizado y nadie lo mira."},
  {"m": "Seguridad y comunidad", "t": "Organizaciones y equipos", "x": "Cuentas compartidas para grupos con equipos y permisos.\n\nUna organización es dueña de repositorios en lugar de una persona. Dentro creas equipos (teams) con permisos y CODEOWNERS indica quién debe revisar cada carpeta. Si alguien sale, el código sigue en la organización.", "u": "Que una empresa o un grupo de estudio administre sus repositorios.\n\nTu grupo del SENA quiere que los repositorios del proyecto no dependan de la cuenta de una sola persona.", "p": ["Una organización es dueña de repositorios.", "Los equipos agrupan miembros con permisos.", "CODEOWNERS asigna revisores por carpeta."], "c": "# .github/CODEOWNERS\n/backend/  @equipo-backend\n/frontend/ @ana", "h": "Asigna revisores por carpeta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una cuenta compartida por un grupo es una ___. (12 letras)", "e": "Poner los repositorios del grupo en la cuenta personal de alguien."},
  {"m": "Seguridad y comunidad", "t": "Contribuir a open source", "x": "Aportar a proyectos públicos de otras personas.\n\nLee CONTRIBUTING.md y el código de conducta, busca issues con good first issue, haz fork, crea una rama, haz los cambios con pruebas y abre un pull request explicando qué y por qué. También cuentan la documentación y las traducciones.", "u": "Aprender, ganar experiencia real y mejorar tu perfil.\n\nQuieres hacer tu primer aporte a una librería famosa que usas.", "p": ["CONTRIBUTING.md explica cómo contribuir.", "Las contribuciones empiezan con un fork.", "La documentación también es una contribución."], "c": "gh repo fork dueño/libreria --clone\ngit switch -c corrige-typo", "h": "Hace fork, clona y crea una rama.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El archivo con las reglas para contribuir es ___.md. (12 letras)", "e": "Abrir un pull request enorme sin hablar antes con los mantenedores."},
  {"m": "Seguridad y comunidad", "t": "Perfil y portafolio en GitHub", "x": "Tu página de GitHub como carta de presentación.\n\nUn repositorio con tu mismo nombre de usuario muestra su README en tu perfil. Fija (pin) tus seis mejores proyectos, con README, capturas y demo en Pages. La constancia de commits también cuenta.", "u": "Mostrar tus proyectos a empresas y profesores.\n\nVas a postularte a tu primer trabajo y quieres que el reclutador vea tus mejores proyectos en GitHub.", "p": ["Un repositorio con tu nombre de usuario personaliza tu perfil.", "Puedes fijar hasta seis repositorios en tu perfil.", "Los proyectos con demo y README impresionan más."], "c": "# Repositorio: ana/ana  →  README.md\n## Hola, soy Ana 👋\nDesarrolladora web · Python · React", "h": "README especial del perfil.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para mostrar repositorios destacados en el perfil se ___. (5 letras)", "e": "Tener solo repositorios vacíos o sin README."},
  {"m": "Trabaja como en una empresa", "t": "Rulesets", "x": "Reglas que protegen ramas y etiquetas de un repositorio.\n\nEn Settings → Rules creas un ruleset para main: exigir pull request, aprobaciones, pruebas en verde y bloquear el push forzado. Reemplazan y amplían a las antiguas ramas protegidas.", "u": "Impedir que alguien suba directo a main o lo borre.\n\nUn compañero subió directo a main sin revisión y rompió producción.", "p": ["Un ruleset protege ramas o etiquetas.", "Un ruleset puede exigir pull request y pruebas en verde.", "Los rulesets bloquean el push forzado."], "c": "gh api repos/ana/tienda/rulesets --jq '.[].name'", "h": "Lista los rulesets del repositorio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las reglas modernas para proteger ramas se llaman ___ (8 letras, en inglés)", "e": "Dejar main sin protección en un proyecto de equipo."},
  {"m": "Trabaja como en una empresa", "t": "CODEOWNERS", "x": "Archivo que define quién debe revisar cada parte del código.\n\nEn .github/CODEOWNERS escribes /backend/ @ana y *.css @luis. GitHub pide su revisión automáticamente y, con un ruleset, su aprobación es obligatoria.", "u": "Que los cambios lleguen siempre al experto de esa área.\n\nQuieres que cualquier cambio en la carpeta backend sea revisado por Ana automáticamente.", "p": ["CODEOWNERS asigna dueños a partes del código.", "GitHub pide revisión a los dueños automáticamente.", "El archivo va en .github/CODEOWNERS."], "c": "printf \"/backend/ @ana\\n*.css @luis\\n\" > .github/CODEOWNERS\ncat .github/CODEOWNERS", "h": "Asigna dueños al backend y al CSS.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El archivo que define quién revisa cada parte es ___ (10 letras)", "e": "Poner a una sola persona como dueña de todo y frenar al equipo."},
  {"m": "Trabaja como en una empresa", "t": "Pull requests en borrador", "x": "Pull request marcado como «todavía no está listo».\n\nAl crear el PR eliges «Create draft pull request» o gh pr create --draft. No se puede fusionar ni pide revisores hasta que pulses «Ready for review».", "u": "Mostrar avances y recibir ideas sin que lo fusionen.\n\nQuieres que tu equipo vea cómo va tu función a mitad de camino, pero sin que nadie la fusione.", "p": ["Un borrador de PR no se puede fusionar.", "Sirve para mostrar avances y recibir ideas.", "«Ready for review» lo marca como listo."], "c": "gh pr create --draft --title \"Carrito (en progreso)\" --body \"Falta el pago\"", "h": "Abre un borrador de pull request.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para crear un borrador con gh se usa la opción --___ (5 letras)", "e": "Abrir PR normales a medias y que alguien los fusione por error."},
  {"m": "Trabaja como en una empresa", "t": "Sugerencias en revisiones", "x": "Proponer el cambio exacto de una línea dentro de un comentario.\n\nEn la revisión, el botón ± inserta un bloque ```suggestion con la línea. El autor pulsa «Commit suggestion» y el cambio se aplica como un commit.", "u": "Corregir detalles sin que el autor tenga que reescribirlos.\n\nEn una revisión ves un error de ortografía en un texto.", "p": ["Una sugerencia propone el cambio exacto de una línea.", "El autor la aplica con «Commit suggestion».", "Se escribe en un bloque suggestion."], "c": "printf '```suggestion\\nconst total = precio * cantidad;\\n```\\n'", "h": "Escribe una sugerencia de cambio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El bloque para proponer un cambio exacto se llama ___ (10 letras, en inglés)", "e": "Escribir «hay un error por ahí» sin decir cuál."},
  {"m": "Trabaja como en una empresa", "t": "Auto-merge", "x": "Opción para que el pull request se fusione solo cuando cumpla las reglas.\n\nCon «Enable auto-merge» (o gh pr merge --auto --squash), GitHub fusiona apenas haya aprobación y pruebas en verde. Si algo falla, no se fusiona.", "u": "No esperar frente a la pantalla a que terminen las pruebas.\n\nTu PR ya está aprobado pero las pruebas tardan 20 minutos y quieres irte.", "p": ["Auto-merge fusiona cuando se cumplen las reglas.", "Si las pruebas fallan, no se fusiona.", "Se activa con gh pr merge --auto."], "c": "gh pr merge 42 --auto --squash", "h": "Activa la fusión automática.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para activar la fusión automática con gh se usa --___ (4 letras)", "e": "Activar auto-merge sin reglas que exijan pruebas."},
  {"m": "Trabaja como en una empresa", "t": "Merge queue", "x": "Cola que fusiona los pull requests de uno en uno probándolos juntos.\n\nCon merge queue, cada PR se prueba encima de los que van antes en la cola. Si falla, sale de la cola y main nunca queda roto. Se activa en el ruleset de la rama.", "u": "Evitar que dos PR que pasan por separado rompan main al unirse.\n\nDos PR pasan sus pruebas por separado, pero al fusionarlos juntos main queda roto.", "p": ["Merge queue prueba cada PR sobre los anteriores.", "Evita que main se rompa al unir varios PR.", "Si un PR falla, sale de la cola."], "c": "gh pr merge 42 --squash   # con merge queue activo, entra a la cola", "h": "Pone el PR en la cola.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La cola de fusión de GitHub se llama merge ___ (5 letras)", "e": "Fusionar muchos PR a la vez sin probarlos juntos."},
  {"m": "Trabaja como en una empresa", "t": "Vincular issues y PR", "x": "Relacionar un pull request con el issue que resuelve.\n\nEn la descripción del PR escribe Closes #12 (o Fixes, Resolves). Al fusionar en la rama principal, el issue 12 se cierra y queda enlazado.", "u": "Que el issue se cierre solo al fusionar.\n\nSiempre olvidas cerrar el issue después de fusionar el PR que lo arregla.", "p": ["Closes #12 cierra el issue al fusionar el PR.", "Fixes y Resolves funcionan igual.", "El issue queda enlazado con el PR."], "c": "gh pr create --title \"Arregla el login\" --body \"Closes #12\"", "h": "Crea un PR que cierra el issue 12.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra que cierra un issue al fusionar es ___ #12 (6 letras, en inglés)", "e": "Dejar issues abiertos que ya se resolvieron."},
  {"m": "Trabaja como en una empresa", "t": "Milestones", "x": "Agrupar issues y PR que deben estar listos para una fecha o versión.\n\nCreas el milestone «v1.2 – 15 de diciembre» y le asignas issues. GitHub muestra el porcentaje completado según los issues cerrados.", "u": "Saber cuánto falta para la próxima entrega.\n\nEl profesor pide la versión 1.0 para el 15 de diciembre y quieres ver cuánto falta.", "p": ["Un milestone agrupa issues para una entrega.", "Un milestone puede tener fecha límite.", "GitHub muestra el porcentaje completado."], "c": "gh issue edit 12 --milestone \"v1.0\"", "h": "Asigna un issue al milestone v1.0.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una meta con fecha que agrupa issues se llama ___ (9 letras, en inglés)", "e": "Planear entregas sin saber cuántos issues faltan."},
  {"m": "Trabaja como en una empresa", "t": "Listas de tareas y sub-issues", "x": "Dividir un issue grande en tareas más pequeñas.\n\nDentro de un issue escribes - [ ] tareas que se marcan al hacer clic, o creas sub-issues que tienen su propio responsable y estado. El issue padre muestra el progreso.", "u": "Seguir el avance de una funcionalidad grande.\n\nEl issue «Tienda en línea» es enorme y quieres dividirlo en carrito, pago y envíos con responsables distintos.", "p": ["- [ ] crea una casilla de tarea en Markdown.", "Los sub-issues dividen un issue grande.", "El issue padre muestra el progreso de sus partes."], "c": "printf -- \"- [x] Carrito\\n- [ ] Pago\\n- [ ] Envíos\\n\"", "h": "Escribe una lista de tareas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una casilla de tarea marcada se escribe - [___] (1 letra)", "e": "Tener issues gigantes que nunca se cierran."},
  {"m": "Trabaja como en una empresa", "t": "Notificaciones y watch", "x": "Elegir de qué repositorios y conversaciones te avisa GitHub.\n\nWatch → «Participating and @mentions» solo te avisa cuando te mencionan o participas. «All activity» avisa todo. En github.com/notifications filtras y marcas como leído.", "u": "No perderte lo importante ni ahogarte en avisos.\n\nRecibes 200 correos diarios de un repositorio donde casi no participas.", "p": ["Watch decide qué avisos recibes de un repositorio.", "«Participating» solo avisa si te mencionan o participas.", "Las notificaciones se revisan en github.com/notifications."], "c": "gh api notifications --jq 'length'", "h": "Cuenta tus notificaciones.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción para seguir un repositorio se llama ___ (5 letras, en inglés)", "e": "Seguir todos los repositorios con «All activity»."},
  {"m": "Trabaja como en una empresa", "t": "Búsqueda avanzada en GitHub", "x": "Filtros para encontrar código, issues y repositorios.\n\nis:issue is:open label:bug author:@me filtra issues. En código: language:python path:tests \"def test_\". En repositorios: stars:>1000 topic:react.", "u": "Encontrar ejemplos reales o issues concretos rápido.\n\nQuieres ver solo los issues abiertos con la etiqueta bug que te asignaron.", "p": ["is:open filtra lo que está abierto.", "language: filtra por lenguaje.", "stars:>1000 busca repositorios populares."], "c": "gh search repos --stars=\">50000\" --language=typescript --limit 1 --json name --jq '.[].name'", "h": "Busca un repositorio popular de TypeScript.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El filtro para buscar por lenguaje es ___: (8 letras, en inglés)", "e": "Buscar ejemplos en sitios viejos en vez de en código real de GitHub."},
  {"m": "Trabaja como en una empresa", "t": "Atajos de teclado de GitHub", "x": "Teclas que aceleran la navegación en GitHub.\n\nt abre el buscador de archivos, . abre el editor github.dev, y luego pr va a pull requests, / enfoca la búsqueda y ? muestra todos los atajos.", "u": "Moverte por repositorios sin el mouse.\n\nEstás en un repositorio con 3000 archivos y quieres abrir uno por su nombre rápido.", "p": ["La tecla t busca archivos en un repositorio.", "La tecla . abre el editor github.dev.", "La tecla ? muestra todos los atajos."], "c": "echo \"t: buscar archivo · .: editor · ?: ayuda\"", "h": "Recuerda tres atajos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La tecla para buscar archivos en un repositorio es ___ (1 letra)", "e": "Navegar carpeta por carpeta en repositorios enormes."},
  {"m": "Trabaja como en una empresa", "t": "github.dev", "x": "Editor de VS Code en el navegador para cualquier repositorio.\n\nPulsando . en un repositorio o cambiando github.com por github.dev se abre VS Code en el navegador. Sirve para editar y hacer commits, pero no ejecuta código (para eso, Codespaces).", "u": "Hacer cambios rápidos sin clonar ni instalar nada.\n\nDesde el computador de la biblioteca quieres corregir un texto en tres archivos y hacer commit sin instalar nada.", "p": ["github.dev abre VS Code en el navegador.", "Se abre pulsando la tecla punto en un repositorio.", "github.dev no ejecuta código; Codespaces sí."], "c": "echo \"https://github.dev/ana/tienda\"", "h": "Muestra la dirección del editor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para abrir github.dev en un repositorio se pulsa la tecla ___ (1 carácter)", "e": "Esperar que github.dev ejecute tu servidor."},
  {"m": "Trabaja como en una empresa", "t": "Respuestas guardadas", "x": "Textos que guardas para responder rápido en issues y PR.\n\nEn Settings → Saved replies guardas, por ejemplo, «Gracias por el reporte, ¿puedes compartir los pasos para reproducirlo?». En cualquier comentario las insertas con un clic o Ctrl+.", "u": "No escribir una y otra vez las mismas respuestas.\n\nMantienes un proyecto y respondes 10 veces por semana pidiendo pasos para reproducir el error.", "p": ["Las respuestas guardadas ahorran texto repetido.", "Se crean en Settings → Saved replies.", "Se insertan en cualquier comentario."], "c": "echo \"Gracias por el reporte. ¿Qué pasos sigo para ver el error?\"", "h": "Muestra una respuesta guardada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las respuestas guardadas están en Settings → Saved ___ (7 letras, en inglés)", "e": "Responder de forma brusca por cansancio de escribir lo mismo."},
  {"m": "Trabaja como en una empresa", "t": "Insights del repositorio", "x": "Estadísticas de actividad, colaboradores y tráfico.\n\nInsights → Contributors muestra commits por persona, Traffic las visitas y clones de los últimos 14 días, y Pulse el resumen de la semana.", "u": "Ver quién contribuye y cuántas visitas tiene tu proyecto.\n\nQuieres saber cuántas personas visitaron tu portafolio en GitHub la última semana.", "p": ["Insights muestra estadísticas del repositorio.", "Traffic muestra visitas de los últimos 14 días.", "Contributors muestra la actividad de cada persona."], "c": "gh api repos/ana/tienda/traffic/views --jq '.count'", "h": "Cuenta las visitas del repositorio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las estadísticas del repositorio están en la pestaña ___ (8 letras, en inglés)", "e": "Evaluar un proyecto solo por sus estrellas."},
  {"m": "Trabaja como en una empresa", "t": "Archivar y transferir", "x": "Dejar un repositorio de solo lectura o pasarlo a otra cuenta.\n\nSettings → Archive deja el repositorio de solo lectura con un aviso. Transfer lo pasa a otra cuenta u organización y GitHub redirige los enlaces viejos.", "u": "Cerrar proyectos viejos o entregarlos a una organización.\n\nTerminaste un proyecto del colegio y no lo vas a mantener, pero quieres que siga visible.", "p": ["Archivar deja un repositorio en solo lectura.", "Transferir pasa un repositorio a otra cuenta.", "Tras transferir, GitHub redirige los enlaces viejos."], "c": "gh repo archive ana/proyecto-viejo --yes", "h": "Archiva un repositorio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para dejar un repositorio en solo lectura se usa ___ (7 letras, en inglés)", "e": "Borrar repositorios viejos que otros todavía usan."},
  {"m": "Trabaja como en una empresa", "t": "Sincronizar un fork", "x": "Traer a tu fork los cambios nuevos del repositorio original.\n\nEn la web pulsas «Sync fork». En la terminal: gh repo sync o agregas el original como upstream y haces git fetch upstream y merge.", "u": "Que tu copia no quede desactualizada antes de un PR.\n\nTu fork de un proyecto open source tiene 120 commits de atraso y quieres enviar un PR.", "p": ["Un fork se desactualiza con el tiempo.", "«Sync fork» trae los cambios del original.", "El repositorio original se suele llamar upstream."], "c": "gh repo sync ana/vite", "h": "Sincroniza el fork con el original.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El remoto del repositorio original se suele llamar ___ (8 letras)", "e": "Enviar un PR desde un fork muy desactualizado."},
  {"m": "Trabaja como en una empresa", "t": "Etiquetas de temas", "x": "Palabras clave (topics) que describen un repositorio.\n\nEn el «About» del repositorio agregas topics como react, portfolio o flask. Aparecen como enlaces y GitHub agrupa los repositorios en github.com/topics.", "u": "Que otros encuentren tu proyecto.\n\nTu proyecto de Flask no aparece cuando alguien busca proyectos de Flask en GitHub.", "p": ["Los topics describen de qué trata un repositorio.", "Ayudan a que otros encuentren tu proyecto.", "Se agregan en la sección About."], "c": "gh repo edit --add-topic flask,python,portfolio", "h": "Agrega temas al repositorio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las palabras clave de un repositorio se llaman ___ (6 letras, en inglés)", "e": "Dejar el repositorio sin descripción ni topics."},
  {"m": "Trabaja como en una empresa", "t": "Repositorios privados y visibilidad", "x": "Decidir quién puede ver un repositorio.\n\nPúblico: lo ve cualquiera. Privado: solo tú y los colaboradores. Internal (en organizaciones): todos los miembros. Cambiar a público expone también todo el historial.", "u": "Proteger proyectos de clientes o trabajos sin terminar.\n\nAntes de hacer público un repositorio privado,", "p": ["Un repositorio privado solo lo ven los colaboradores.", "Hacerlo público expone todo su historial.", "Internal es visible para toda la organización."], "c": "gh repo edit --visibility private --accept-visibility-change-consequences", "h": "Hace privado el repositorio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La visibilidad para que solo lo vean los colaboradores es ___ (7 letras, en inglés)", "e": "Publicar un repositorio con contraseñas en commits viejos."},
  {"m": "Trabaja como en una empresa", "t": "Comentarios con Markdown", "x": "Dar formato a issues, PR y comentarios.\n\nBloques de código con ```js, listas, tablas, > citas, @menciones, #referencias a issues, emojis :rocket: y alertas como > [!WARNING]. Puedes pegar imágenes y videos.", "u": "Que tus reportes y revisiones se entiendan rápido.\n\nReportas un error y quieres que tu código se vea con colores dentro del issue.", "p": ["Los comentarios de GitHub aceptan Markdown.", "```js crea un bloque de código con colores.", "> [!WARNING] crea una alerta destacada."], "c": "printf '> [!WARNING]\\n> No subas tu archivo .env\\n'", "h": "Escribe una alerta en Markdown.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las alertas de GitHub se escriben como > [!___] (7 letras, la de advertencia)", "e": "Pegar código sin formato en un issue."},
  {"m": "Actions a fondo", "t": "Caché en Actions", "x": "Guardar dependencias entre ejecuciones de un workflow.\n\nactions/setup-node con cache: npm o actions/cache con una key basada en el package-lock.json. Si el archivo no cambia, se reutiliza y el workflow tarda mucho menos.", "u": "Que las pruebas no instalen todo desde cero cada vez.\n\nTu workflow tarda 4 minutos solo en npm install cada vez.", "p": ["La caché guarda dependencias entre ejecuciones.", "La key de la caché suele basarse en el archivo de bloqueo.", "Si la key no cambia, se reutiliza la caché."], "c": "printf \"      - uses: actions/setup-node@v4\\n        with:\\n          cache: npm\\n\"", "h": "Activa la caché de npm.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La acción general para guardar caché es actions/___ (5 letras)", "e": "Guardar en caché la carpeta de resultados de las pruebas."},
  {"m": "Actions a fondo", "t": "Variables y contextos", "x": "Datos disponibles en un workflow con la sintaxis ${{ }}.\n\n${{ github.ref_name }} es la rama, ${{ github.actor }} quien lo lanzó, ${{ vars.URL }} una variable del repositorio y ${{ secrets.TOKEN }} un secreto. env: define variables de entorno.", "u": "Usar la rama, el autor o tus variables dentro de los pasos.\n\nTu workflow debe mostrar en qué rama se está ejecutando.", "p": ["${{ }} inserta valores en un workflow.", "github.ref_name es el nombre de la rama.", "vars guarda variables no secretas del repositorio."], "c": "echo \"rama: ${GITHUB_REF_NAME:-main}\"", "h": "Muestra la rama del workflow.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las variables no secretas del repositorio están en el contexto ___ (4 letras)", "e": "Poner valores sensibles en vars en lugar de secrets."},
  {"m": "Actions a fondo", "t": "Condiciones con if", "x": "Ejecutar un paso o job solo si se cumple algo.\n\nif: github.ref == 'refs/heads/main' limita a main; if: failure() se ejecuta solo si un paso anterior falló y if: always() siempre, por ejemplo para subir reportes.", "u": "Desplegar solo desde main o solo si falló algo.\n\nQuieres que el paso de despliegue solo corra en la rama main, no en otras ramas.", "p": ["if decide si un paso o job se ejecuta.", "failure() es verdadero si algo falló antes.", "always() ejecuta el paso pase lo que pase."], "c": "printf \"    if: github.ref == 'refs/heads/main'\\n\"", "h": "Limita un paso a main.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que se cumple si algo falló antes es ___() (7 letras, en inglés)", "e": "Desplegar desde cualquier rama por no poner condiciones."},
  {"m": "Actions a fondo", "t": "Jobs dependientes", "x": "Hacer que un job espere a que termine otro.\n\nneeds: pruebas hace que el job deploy espere al job pruebas y no corra si falla. Sin needs, los jobs se ejecutan en paralelo.", "u": "Desplegar solo después de que pasen las pruebas.\n\nTu job de despliegue arranca al mismo tiempo que las pruebas y publica aunque fallen.", "p": ["needs hace que un job espere a otro.", "Sin needs los jobs corren en paralelo.", "Si el job necesario falla, el siguiente no se ejecuta."], "c": "printf \"  deploy:\\n    needs: pruebas\\n\"", "h": "Hace que deploy espere a las pruebas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La palabra para que un job espere a otro es ___ (5 letras, en inglés)", "e": "Desplegar sin esperar a que pasen las pruebas."},
  {"m": "Actions a fondo", "t": "Concurrencia en workflows", "x": "Evitar que corran a la vez dos ejecuciones del mismo workflow.\n\nconcurrency: { group: deploy-${{ github.ref }}, cancel-in-progress: true } cancela la ejecución vieja cuando llega una nueva del mismo grupo.", "u": "No tener dos despliegues pisándose.\n\nHaces 3 pushes seguidos y se lanzan 3 despliegues a la vez que se pisan.", "p": ["concurrency agrupa ejecuciones que no deben ir a la vez.", "cancel-in-progress cancela la ejecución anterior.", "Evita despliegues que se pisan."], "c": "printf \"concurrency:\\n  group: deploy\\n  cancel-in-progress: true\\n\"", "h": "Cancela despliegues viejos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La clave para evitar ejecuciones simultáneas es ___ (11 letras, en inglés)", "e": "Dejar que varios despliegues corran a la vez."},
  {"m": "Actions a fondo", "t": "Entornos y aprobaciones", "x": "Environments con reglas, secretos propios y aprobación manual.\n\nEn Settings → Environments creas production con revisores obligatorios y sus propios secretos. Un job con environment: production espera la aprobación.", "u": "Que nadie despliegue a producción sin permiso.\n\nQuieres que el despliegue a producción espere a que el profesor lo apruebe.", "p": ["Un environment tiene sus propios secretos.", "Un environment puede exigir aprobación manual.", "El job indica su entorno con environment:."], "c": "printf \"  deploy:\\n    environment: production\\n\"", "h": "Asigna el entorno de producción.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los entornos de despliegue se llaman ___ (12 letras, en inglés)", "e": "Usar los mismos secretos para pruebas y producción."},
  {"m": "Actions a fondo", "t": "Lanzar workflows a mano", "x": "Ejecutar un workflow con un botón y con datos de entrada.\n\non: workflow_dispatch con inputs (por ejemplo, entorno: staging o production) agrega el botón «Run workflow». También: gh workflow run deploy.yml -f entorno=staging.", "u": "Hacer despliegues o tareas cuando tú decidas.\n\nQuieres un botón para desplegar cuando tú quieras, eligiendo el entorno.", "p": ["workflow_dispatch permite lanzar un workflow a mano.", "inputs pide datos al lanzarlo.", "gh workflow run lo lanza desde la terminal."], "c": "gh workflow run deploy.yml -f entorno=staging", "h": "Lanza el despliegue a staging.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El evento para lanzar un workflow a mano es workflow___ (9 letras, con guion bajo)", "e": "Hacer pushes vacíos solo para lanzar un workflow."},
  {"m": "Actions a fondo", "t": "Workflows programados", "x": "Ejecutar un workflow automáticamente a cierta hora.\n\non: schedule: - cron: '0 6 * * 1' se ejecuta los lunes a las 6:00 UTC. GitHub puede retrasarlo en horas pico y lo desactiva si el repositorio no tiene actividad en 60 días.", "u": "Hacer respaldos, reportes o revisiones cada día.\n\nQuieres revisar cada mañana si tus enlaces siguen funcionando.", "p": ["schedule ejecuta un workflow con sintaxis cron.", "Las horas de schedule están en UTC.", "GitHub desactiva schedules de repositorios inactivos."], "c": "printf \"on:\\n  schedule:\\n    - cron: '0 11 * * *'\\n\"", "h": "Programa una ejecución diaria.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El evento para ejecutar a cierta hora es ___ (8 letras, en inglés)", "e": "Programar cada minuto y gastar los minutos gratuitos."},
  {"m": "Actions a fondo", "t": "Permisos del GITHUB_TOKEN", "x": "Limitar lo que puede hacer el token automático de cada workflow.\n\npermissions: contents: read al inicio del workflow da solo lectura. Agrega solo lo necesario, como pull-requests: write para comentar.", "u": "Que un workflow comprometido no pueda dañar el repositorio.\n\nUna auditoría dice que tus workflows tienen permisos de escritura en todo.", "p": ["GITHUB_TOKEN se crea solo en cada ejecución.", "permissions limita lo que puede hacer el token.", "Se debe dar el mínimo de permisos necesario."], "c": "printf \"permissions:\\n  contents: read\\n\"", "h": "Deja el token en solo lectura.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La clave para limitar el token es ___ (11 letras, en inglés)", "e": "Dar permisos de escritura a todos los workflows."},
  {"m": "Actions a fondo", "t": "Servicios en un job", "x": "Levantar una base de datos u otro contenedor durante las pruebas.\n\nservices: mysql: image: mysql:8 con env y ports levanta MySQL junto al job. Tus pruebas se conectan a localhost:3306 como en tu PC.", "u": "Probar tu API contra MySQL o Redis reales.\n\nTus pruebas de la API necesitan un MySQL de verdad en GitHub Actions.", "p": ["services levanta contenedores durante el job.", "Sirve para probar contra bases de datos reales.", "Los servicios se configuran con imagen, variables y puertos."], "c": "printf \"    services:\\n      mysql:\\n        image: mysql:8\\n\"", "h": "Agrega MySQL al job.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La clave para levantar contenedores en un job es ___ (8 letras, en inglés)", "e": "Probar contra una base de datos de producción desde CI."},
  {"m": "Actions a fondo", "t": "Workflows reutilizables", "x": "Workflows que otros workflows llaman como si fueran un job.\n\nEl workflow compartido usa on: workflow_call con inputs y secrets. Otro lo llama con uses: org/plantillas/.github/workflows/pruebas.yml@main.", "u": "No copiar la misma configuración en 10 repositorios.\n\nTienes el mismo workflow de pruebas copiado en 8 repositorios y cada cambio hay que hacerlo 8 veces.", "p": ["workflow_call permite reutilizar un workflow.", "Se llama con uses: y la ruta del workflow.", "Pueden recibir inputs y secretos."], "c": "printf \"on:\\n  workflow_call:\\n\"", "h": "Declara un workflow reutilizable.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El evento de un workflow reutilizable es workflow___ (5 letras, con guion bajo)", "e": "Copiar y pegar el mismo YAML en muchos repositorios."},
  {"m": "Actions a fondo", "t": "Acciones compuestas", "x": "Acción propia que agrupa varios pasos en uno.\n\nEn .github/actions/preparar/action.yml defines runs: using: composite y la lista de steps. Luego en cualquier workflow: uses: ./.github/actions/preparar.", "u": "Reutilizar pasos repetidos dentro de tus workflows.\n\nEn 5 jobs repites los mismos 4 pasos de preparación.", "p": ["Una acción compuesta agrupa varios pasos.", "Se declara con using: composite.", "Se usa con la ruta de su carpeta."], "c": "printf \"runs:\\n  using: composite\\n\"", "h": "Declara una acción compuesta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una acción que agrupa pasos se declara con using: ___ (9 letras, en inglés)", "e": "Repetir los mismos pasos en todos los jobs."},
  {"m": "Actions a fondo", "t": "Crear tu propia acción", "x": "Publicar una acción con JavaScript o Docker para que otros la usen.\n\nUna acción de JavaScript tiene action.yml con runs: using: node20 y main: index.js, y usa @actions/core para leer inputs. Se publica en el Marketplace con un release.", "u": "Compartir automatizaciones con la comunidad.\n\nHiciste una automatización útil y quieres que otros repositorios la usen con uses: ana/mi-accion@v1.", "p": ["Una acción puede escribirse con JavaScript.", "@actions/core lee los inputs de la acción.", "Las acciones se publican en el Marketplace."], "c": "printf \"runs:\\n  using: node20\\n  main: index.js\\n\"", "h": "Declara una acción de JavaScript.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El paquete para leer inputs en una acción es @actions/___ (4 letras)", "e": "Usar acciones de terceros sin fijar su versión."},
  {"m": "Actions a fondo", "t": "Fijar versiones de acciones", "x": "Usar una versión concreta de cada acción en lugar de una rama.\n\nuses: actions/checkout@v4 fija la versión mayor; fijar al hash completo del commit es lo más seguro. Dependabot puede actualizar esas versiones por ti.", "u": "Que un cambio ajeno no rompa ni comprometa tu workflow.\n\nUsas una acción de terceros con @main y un día cambió y rompió tus despliegues.", "p": ["Fijar versiones evita cambios inesperados.", "Fijar al hash del commit es lo más seguro.", "Dependabot puede actualizar las acciones."], "c": "echo \"uses: actions/checkout@v4\"", "h": "Muestra una acción con versión fija.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Lo más seguro es fijar una acción al ___ de su commit (4 letras, en inglés)", "e": "Usar acciones con @main en workflows con secretos."},
  {"m": "Actions a fondo", "t": "Desplegar Pages con Actions", "x": "Publicar en GitHub Pages el resultado de compilar tu proyecto.\n\nEn Settings → Pages eliges «GitHub Actions». El workflow hace el build, sube la carpeta con actions/upload-pages-artifact y publica con actions/deploy-pages.", "u": "Publicar sitios de React o Vite que necesitan npm run build.\n\nTu app de React necesita npm run build antes de publicarse en Pages.", "p": ["Pages puede publicarse desde un workflow.", "upload-pages-artifact sube la carpeta del build.", "deploy-pages publica el sitio."], "c": "echo \"uses: actions/deploy-pages@v4\"", "h": "Muestra la acción que publica.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La acción que publica en Pages es actions/deploy-___ (5 letras)", "e": "Subir la carpeta dist a main para publicarla."},
  {"m": "Actions a fondo", "t": "OIDC para la nube", "x": "Iniciar sesión en AWS, Azure o Google Cloud desde Actions sin guardar claves.\n\nCon permissions: id-token: write, el workflow pide un token temporal que la nube acepta según el repositorio y la rama. No hay que guardar claves de acceso como secretos.", "u": "Desplegar a la nube sin secretos de larga duración.\n\nGuardas la clave de AWS en un secreto que nunca vence y temes que se filtre.", "p": ["OIDC evita guardar claves de la nube como secretos.", "El token de OIDC es temporal.", "Necesita el permiso id-token: write."], "c": "printf \"permissions:\\n  id-token: write\\n\"", "h": "Permite pedir tokens OIDC.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El estándar para iniciar sesión en la nube sin claves es ___ (4 letras)", "e": "Guardar claves de la nube que nunca vencen."},
  {"m": "Actions a fondo", "t": "Runners propios", "x": "Computadores tuyos que ejecutan los workflows en lugar de los de GitHub.\n\nEn Settings → Actions → Runners registras tu equipo y en el workflow usas runs-on: self-hosted. Úsalos solo en repositorios privados: un PR ajeno podría ejecutar código en tu equipo.", "u": "Usar hardware especial o redes privadas.\n\nTus pruebas necesitan una GPU que los runners de GitHub no tienen.", "p": ["Un runner propio ejecuta workflows en tu equipo.", "Se usa con runs-on: self-hosted.", "No se recomiendan en repositorios públicos."], "c": "echo \"runs-on: self-hosted\"", "h": "Usa un runner propio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los runners propios se indican con runs-on: self-___ (6 letras, en inglés)", "e": "Usar runners propios en repositorios públicos."},
  {"m": "Actions a fondo", "t": "Badges de estado", "x": "Imagen que muestra si el workflow está en verde o en rojo.\n\nLa URL https://github.com/ana/tienda/actions/workflows/ci.yml/badge.svg da la imagen; la pones en el README con ![CI](url).", "u": "Mostrar en el README que tu proyecto pasa las pruebas.\n\nQuieres que cualquiera vea en tu README que las pruebas pasan.", "p": ["Un badge muestra el estado de un workflow.", "La imagen termina en badge.svg.", "Se agrega al README con sintaxis de imagen."], "c": "echo \"![CI](https://github.com/ana/tienda/actions/workflows/ci.yml/badge.svg)\"", "h": "Escribe el badge del README.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La imagen del estado de un workflow termina en badge.___ (3 letras)", "e": "Mostrar un badge de un workflow que ya no existe."},
  {"m": "Actions a fondo", "t": "Depurar workflows", "x": "Encontrar por qué falla un workflow.\n\nActiva el secreto o variable ACTIONS_STEP_DEBUG=true para logs detallados, usa «Re-run with debug logging», gh run view --log-failed muestra solo lo que falló y act ejecuta workflows en tu PC.", "u": "Arreglar errores de CI sin hacer veinte pushes de prueba.\n\nTu workflow falla y quieres ver solo el log de los pasos que fallaron desde la terminal.", "p": ["ACTIONS_STEP_DEBUG activa logs detallados.", "gh run view --log-failed muestra los pasos fallidos.", "act ejecuta workflows en tu computador."], "c": "gh run view --log-failed | head -1", "h": "Muestra el log del paso que falló.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La herramienta que ejecuta workflows en tu PC se llama ___ (3 letras)", "e": "Hacer pushes de prueba uno tras otro sin leer el log."},
  {"m": "Actions a fondo", "t": "Minutos y límites de Actions", "x": "Cuánto tiempo de ejecución gratis tienes y cómo ahorrarlo.\n\nEn repositorios públicos Actions es gratis; en privados hay minutos al mes según el plan, y macOS gasta más que Linux. Usa caché, paths para ejecutar solo si cambió cierto código y concurrency.", "u": "No quedarte sin minutos a mitad de mes.\n\nTu repositorio privado agota los minutos porque el workflow corre aunque solo cambies el README.", "p": ["En repositorios públicos Actions es gratis.", "Los runners de macOS gastan más minutos que Linux.", "paths evita ejecutar si no cambió el código relevante."], "c": "printf \"on:\\n  push:\\n    paths: ['src/**']\\n\"", "h": "Ejecuta solo si cambia src.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El filtro para ejecutar solo si cambian ciertas carpetas es ___ (5 letras, en inglés)", "e": "Ejecutar todas las pruebas por cambiar una coma del README."},
  {"m": "API, automatización y comunidad", "t": "API REST de GitHub", "x": "Interfaz para manejar GitHub con peticiones HTTP.\n\nGET https://api.github.com/repos/ana/tienda devuelve los datos del repositorio. Con un token en la cabecera Authorization puedes crear issues, PR y más. Tiene límites de peticiones por hora.", "u": "Automatizar tareas como crear issues o leer estadísticas.\n\nQuieres un script que cree un issue automáticamente cuando tu servidor detecte un error.", "p": ["La API REST de GitHub responde en JSON.", "Las peticiones autenticadas usan un token.", "La API tiene un límite de peticiones por hora."], "c": "curl -s https://api.github.com/repos/cli/cli | jq -r '.name'", "h": "Lee el nombre de un repositorio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La dirección base de la API es api.___.com (6 letras)", "e": "Hacer miles de peticiones sin token y chocar con el límite."},
  {"m": "API, automatización y comunidad", "t": "API GraphQL de GitHub", "x": "API donde pides exactamente los campos que necesitas en una sola consulta.\n\nPOST a https://api.github.com/graphql con { viewer { login repositories(first: 5) { nodes { name } } } }. Projects y muchas funciones nuevas solo están en GraphQL.", "u": "Traer datos relacionados sin hacer muchas peticiones.\n\nNecesitas tus repositorios con sus últimos 3 issues cada uno y con REST harías 30 peticiones.", "p": ["La API GraphQL trae varios datos en una sola consulta.", "Solo devuelve los campos que pides.", "viewer representa al usuario autenticado."], "c": "gh api graphql -f query='{ viewer { login } }' --jq '.data.viewer.login'", "h": "Pregunta quién eres con GraphQL.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En la API GraphQL, el usuario autenticado es ___ (6 letras, en inglés)", "e": "Pedir todos los campos posibles en cada consulta."},
  {"m": "API, automatización y comunidad", "t": "Tokens de acceso fine-grained", "x": "Tokens personales con permisos limitados a ciertos repositorios.\n\nEn Settings → Developer settings → Fine-grained tokens eliges repositorios, permisos (por ejemplo issues: write) y fecha de vencimiento. Son más seguros que los tokens clásicos.", "u": "Dar a un script solo el acceso que necesita.\n\nTu script solo necesita crear issues en un repositorio y no quieres darle acceso a todo tu GitHub.", "p": ["Un token fine-grained se limita a ciertos repositorios.", "Se eligen permisos concretos para el token.", "Los tokens deben tener fecha de vencimiento."], "c": "echo \"github_pat_...\"  # nunca lo subas al repositorio", "h": "Muestra cómo empieza un token.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los tokens con permisos limitados se llaman ___-grained (4 letras, en inglés)", "e": "Crear tokens con todos los permisos y sin vencimiento."},
  {"m": "API, automatización y comunidad", "t": "GitHub Apps", "x": "Aplicaciones que se instalan en repositorios con permisos propios.\n\nUna GitHub App tiene permisos definidos y se instala en cuentas o repositorios concretos. Actúa como bot (nombre[bot]) y sus tokens duran una hora. Ideal para integraciones serias.", "u": "Crear bots que actúan con su propia identidad.\n\nQuieres un bot que responda issues en varios repositorios con su propio nombre, no con tu cuenta.", "p": ["Una GitHub App tiene su propia identidad de bot.", "Se instala solo en los repositorios elegidos.", "Sus tokens de instalación duran poco."], "c": "echo \"mi-bot[bot] comentó en #12\"", "h": "Muestra cómo aparece un bot.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las aplicaciones con identidad propia en GitHub son las GitHub ___ (4 letras, en inglés)", "e": "Usar tu token personal para un bot del equipo."},
  {"m": "API, automatización y comunidad", "t": "Webhooks", "x": "Avisos que GitHub envía a tu servidor cuando pasa algo.\n\nEn Settings → Webhooks pones la URL de tu servidor y eliges eventos. GitHub envía un POST con JSON; verifica la firma X-Hub-Signature-256 con tu secreto para saber que es real.", "u": "Reaccionar al instante a un push, un issue o un PR.\n\nQuieres que tu servidor se actualice solo cada vez que haces push a main.", "p": ["Un webhook envía un POST a tu servidor cuando ocurre un evento.", "Se eligen los eventos que se quieren recibir.", "La firma X-Hub-Signature-256 prueba que el aviso es real."], "c": "echo \"POST /webhook  X-GitHub-Event: push\"", "h": "Muestra cómo llega un aviso.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La cabecera con la firma del webhook es X-Hub-Signature-___ (3 dígitos)", "e": "Aceptar webhooks sin verificar la firma."},
  {"m": "API, automatización y comunidad", "t": "gh api", "x": "Orden de GitHub CLI para llamar a la API ya autenticado.\n\ngh api repos/{owner}/{repo}/issues lista issues del repositorio actual; -f envía campos; --jq filtra el JSON; --paginate recorre todas las páginas.", "u": "Hacer consultas a la API desde la terminal sin manejar tokens.\n\nQuieres listar los títulos de todos los issues abiertos de tu repositorio desde la terminal.", "p": ["gh api llama a la API con tu sesión de gh.", "--jq filtra la respuesta JSON.", "--paginate trae todas las páginas."], "c": "gh api repos/cli/cli --jq '.stargazers_count > 1000'", "h": "Consulta si el repositorio es popular.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para traer todas las páginas con gh api se usa --___ (8 letras, en inglés)", "e": "Copiar tokens en scripts cuando gh ya está autenticado."},
  {"m": "API, automatización y comunidad", "t": "Octokit", "x": "Biblioteca oficial para usar la API de GitHub desde JavaScript.\n\nconst octokit = new Octokit({ auth: token }); await octokit.rest.issues.create({ owner, repo, title }). En Actions se usa con github-script sin instalar nada.", "u": "Automatizar GitHub desde Node o desde una acción.\n\nTu app de Node debe abrir issues en GitHub cuando un usuario reporta un error.", "p": ["Octokit es la biblioteca oficial de la API de GitHub.", "octokit.rest agrupa los métodos de la API REST.", "actions/github-script trae Octokit listo en un workflow."], "c": "echo \"octokit.rest.issues.create({ owner, repo, title })\"", "h": "Muestra cómo crear un issue.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La biblioteca oficial de JavaScript para la API de GitHub es ___ (7 letras)", "e": "Armar peticiones HTTP a mano cuando existe la biblioteca oficial."},
  {"m": "API, automatización y comunidad", "t": "GitHub Copilot", "x": "Asistente de IA de GitHub que sugiere código y responde preguntas.\n\nCopilot sugiere código en el editor, explica código en el chat, revisa pull requests y puede trabajar en issues como agente. Es gratis para estudiantes verificados.", "u": "Escribir código más rápido y entender proyectos nuevos.\n\nEres estudiante y quieres un asistente de IA en VS Code sin pagar.", "p": ["Copilot sugiere código mientras escribes.", "Copilot puede revisar pull requests.", "Es gratis para estudiantes verificados."], "c": "echo \"Copilot: sugerencia aceptada con Tab\"", "h": "Muestra cómo se acepta una sugerencia.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El asistente de IA de GitHub se llama GitHub ___ (7 letras)", "e": "Aceptar código sugerido sin entenderlo ni probarlo."},
  {"m": "API, automatización y comunidad", "t": "Avisos de seguridad", "x": "Reportar y publicar vulnerabilidades de tu proyecto de forma privada.\n\nEn Security → Advisories alguien reporta en privado, trabajas el arreglo en un fork privado y publicas el aviso con un CVE cuando salga la versión corregida.", "u": "Arreglar fallos de seguridad antes de que se hagan públicos.\n\nAlguien encontró una falla grave en tu librería.", "p": ["Las vulnerabilidades se reportan en privado.", "El arreglo se prepara antes de publicar el aviso.", "Un aviso puede recibir un identificador CVE."], "c": "echo \"GHSA-xxxx-xxxx-xxxx\"", "h": "Muestra el formato de un aviso.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las vulnerabilidades públicas reciben un identificador ___ (3 letras)", "e": "Pedir que reporten fallos de seguridad en issues públicos."},
  {"m": "API, automatización y comunidad", "t": "SECURITY.md", "x": "Archivo que explica cómo reportar vulnerabilidades del proyecto.\n\nEn SECURITY.md indicas qué versiones tienen soporte y cómo reportar en privado (correo o «Report a vulnerability»). GitHub lo muestra en la pestaña Security.", "u": "Que quien encuentre un fallo sepa a quién avisar.\n\nTu proyecto open source crece y quieres decir cómo reportar fallos de seguridad.", "p": ["SECURITY.md explica cómo reportar fallos de seguridad.", "Indica qué versiones tienen soporte.", "GitHub lo muestra en la pestaña Security."], "c": "head -1 SECURITY.md", "h": "Muestra el título del archivo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El archivo con la política de seguridad es ___.md (8 letras)", "e": "No tener forma privada de reportar fallos."},
  {"m": "API, automatización y comunidad", "t": "Grafo de dependencias", "x": "Lista de todas las librerías que usa tu proyecto.\n\nInsights → Dependency graph muestra dependencias directas e indirectas. Puedes exportar un SBOM (lista de materiales del software), cada vez más pedido por empresas.", "u": "Saber qué dependes y exportar un SBOM.\n\nUn cliente te pide la lista de todas las librerías que usa tu software.", "p": ["El grafo de dependencias lista las librerías del proyecto.", "Incluye dependencias directas e indirectas.", "Se puede exportar como SBOM."], "c": "gh api repos/cli/cli/dependency-graph/sbom --jq '.sbom.spdxVersion'", "h": "Pide el SBOM del repositorio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La lista de materiales del software se llama ___ (4 letras)", "e": "No saber qué librerías trae tu proyecto por dentro."},
  {"m": "API, automatización y comunidad", "t": "CONTRIBUTING.md", "x": "Guía para quien quiere contribuir a tu proyecto.\n\nExplica cómo instalar, ejecutar las pruebas, el estilo de commits y cómo abrir un PR. GitHub muestra un enlace a esta guía al abrir issues o PR.", "u": "Recibir contribuciones con el formato y los pasos correctos.\n\nTe llegan PR sin pruebas y con estilos distintos.", "p": ["CONTRIBUTING.md explica cómo contribuir.", "Incluye cómo instalar y probar el proyecto.", "GitHub lo enlaza al abrir issues o PR."], "c": "head -1 CONTRIBUTING.md", "h": "Muestra el título de la guía.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La guía para contribuir se llama ___.md (12 letras)", "e": "Rechazar contribuciones sin haber explicado las reglas."},
  {"m": "API, automatización y comunidad", "t": "Código de conducta", "x": "Reglas de comportamiento para la comunidad de un proyecto.\n\nCODE_OF_CONDUCT.md (por ejemplo, Contributor Covenant) define qué comportamiento se espera, qué no se acepta y a quién reportar. GitHub lo puede agregar desde una plantilla.", "u": "Tener un espacio respetuoso y saber cómo actuar ante abusos.\n\nEn los issues de tu proyecto empiezan los insultos y no tienes reglas escritas.", "p": ["El código de conducta define el comportamiento esperado.", "Indica a quién reportar comportamientos inaceptables.", "Contributor Covenant es una plantilla común."], "c": "ls CODE_OF_CONDUCT.md", "h": "Comprueba que existe el archivo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La plantilla de código de conducta más usada es Contributor ___ (8 letras)", "e": "Moderar sin reglas claras y de forma arbitraria."},
  {"m": "API, automatización y comunidad", "t": "Good first issue", "x": "Etiqueta para issues fáciles pensados para nuevos colaboradores.\n\nEtiquetas issues sencillos y bien explicados con good first issue. GitHub los muestra en github.com/<repo>/contribute y en búsquedas de principiantes.", "u": "Atraer gente que contribuye por primera vez.\n\nQuieres hacer tu primera contribución a open source y buscas tareas fáciles.", "p": ["good first issue marca tareas para principiantes.", "Un buen issue para empezar está bien explicado.", "GitHub lista estos issues en /contribute."], "c": "gh search issues --label \"good first issue\" --state open --limit 1 --json title --jq 'length'", "h": "Busca un issue para principiantes.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La etiqueta para principiantes es good first ___ (5 letras, en inglés)", "e": "Etiquetar como fácil una tarea sin explicar nada."},
  {"m": "API, automatización y comunidad", "t": "GitHub Sponsors", "x": "Programa para recibir donaciones mensuales por tu trabajo open source.\n\nCon un perfil de Sponsors defines niveles de apoyo. El archivo .github/FUNDING.yml agrega el botón «Sponsor» en tus repositorios.", "u": "Sostener económicamente un proyecto.\n\nTu librería es usada por miles de personas y quieres que puedan apoyarte con dinero.", "p": ["GitHub Sponsors permite recibir donaciones.", "FUNDING.yml agrega el botón Sponsor al repositorio.", "Se pueden definir niveles de apoyo."], "c": "cat .github/FUNDING.yml", "h": "Muestra la configuración de donaciones.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El archivo del botón de donaciones es .github/___.yml (7 letras)", "e": "Mantener solo un proyecto enorme sin pedir apoyo ni ayuda."},
  {"m": "API, automatización y comunidad", "t": "Formularios de issues", "x": "Plantillas YAML con campos para crear issues ordenados.\n\nEn .github/ISSUE_TEMPLATE/bug.yml defines campos (textarea, dropdown, checkboxes) y cuáles son obligatorios. Quien reporta llena un formulario en lugar de un texto libre.", "u": "Recibir reportes de errores con toda la información necesaria.\n\nLos reportes de error te llegan sin versión ni pasos para reproducirlo.", "p": ["Los formularios de issues se escriben en YAML.", "Pueden tener campos obligatorios.", "Van en .github/ISSUE_TEMPLATE."], "c": "grep -c \"required: true\" .github/ISSUE_TEMPLATE/bug.yml", "h": "Cuenta los campos obligatorios.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los formularios de issues se guardan en .github/ISSUE___ (9 caracteres, con guion bajo)", "e": "Pedir 20 campos obligatorios y que nadie reporte."},
  {"m": "API, automatización y comunidad", "t": "Etiquetado automático", "x": "Poner etiquetas a PR e issues automáticamente según su contenido.\n\nactions/labeler pone etiquetas según las carpetas que cambia un PR (por ejemplo, frontend si toca src/components). Se configura en .github/labeler.yml.", "u": "Ordenar el trabajo sin hacerlo a mano.\n\nQuieres que los PR que cambian la carpeta docs reciban la etiqueta documentación solos.", "p": ["actions/labeler etiqueta los PR según los archivos cambiados.", "Se configura en .github/labeler.yml.", "Evita etiquetar a mano cada PR."], "c": "echo \"uses: actions/labeler@v5\"", "h": "Muestra la acción de etiquetas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La acción que etiqueta PR automáticamente es actions/___ (7 letras)", "e": "Olvidar etiquetar y perder el orden del proyecto."},
  {"m": "API, automatización y comunidad", "t": "Issues inactivos", "x": "Cerrar o marcar automáticamente los issues sin actividad.\n\nactions/stale marca con una etiqueta los issues sin actividad durante, por ejemplo, 60 días y los cierra 7 días después si nadie responde. Ajusta los días y excluye etiquetas importantes.", "u": "Que el proyecto no acumule cientos de issues olvidados.\n\nTu proyecto tiene 400 issues abiertos, muchos de hace años y sin respuesta.", "p": ["actions/stale marca los issues sin actividad.", "Los cierra si nadie responde tras un aviso.", "Se pueden excluir etiquetas importantes."], "c": "echo \"uses: actions/stale@v9\"", "h": "Muestra la acción de issues inactivos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La acción que marca issues inactivos es actions/___ (5 letras)", "e": "Cerrar issues importantes solo porque nadie comentó."},
  {"m": "API, automatización y comunidad", "t": "Student Developer Pack", "x": "Beneficios gratis de GitHub y otras empresas para estudiantes.\n\nCon un correo o documento de estudiante en education.github.com obtienes Copilot, Codespaces con más horas, dominios, créditos de nube y cursos gratis.", "u": "Usar herramientas profesionales sin pagar mientras estudias.\n\nEres estudiante y quieres Copilot, un dominio y créditos de nube gratis.", "p": ["El Student Pack da herramientas gratis a estudiantes.", "Incluye Copilot gratis.", "Se solicita en education.github.com."], "c": "echo \"https://education.github.com/pack\"", "h": "Muestra la dirección del programa.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El sitio para solicitarlo es ___.github.com (9 letras)", "e": "Pagar herramientas que como estudiante tienes gratis."},
  {"m": "API, automatización y comunidad", "t": "Mantener un proyecto open source", "x": "Hábitos para cuidar un proyecto que otros usan.\n\nResponde con amabilidad, usa plantillas y automatizaciones, publica releases con notas claras, delega a colaboradores de confianza y pon límites a tu tiempo.", "u": "Que tu proyecto crezca sin agotarte.\n\nTu proyecto se volvió popular y estás agotado respondiendo todo solo.", "p": ["Un mantenedor responde con amabilidad.", "Las automatizaciones ahorran trabajo repetido.", "Delegar ayuda a no agotarse."], "c": "gh release create v2.0.0 --generate-notes", "h": "Publica una versión con notas automáticas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para notas automáticas en un release se usa --generate-___ (5 letras, en inglés)", "e": "Intentar hacerlo todo solo hasta abandonar el proyecto."},
  {"m": "API, automatización y comunidad", "t": "Proyecto final en GitHub", "x": "Un repositorio que muestra todo lo aprendido.\n\nREADME con capturas y badges, licencia, topics, issues y milestones, PR revisados, CI con Actions, despliegue en Pages, releases y archivos de comunidad.", "u": "Impresionar en entrevistas con un proyecto profesional.\n\nQuieres que tu repositorio parezca de una empresa en tu portafolio.", "p": ["Un buen repositorio tiene README, licencia y topics.", "CI y releases muestran profesionalismo.", "Los archivos de comunidad facilitan colaborar."], "c": "ls README.md LICENSE .github/workflows/ci.yml", "h": "Comprueba los archivos clave.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El archivo con la licencia del proyecto se llama ___ (7 letras, en inglés)", "e": "Tener un repositorio sin README ni explicación."}
];
